expenses = []
for note in trip_notes_details:
    content_lines = note['content'].split('\n')
    for line in content_lines:
        if line.startswith('- '):
            parts = line[2:].split('.')
            expense_description = parts[0].strip()
            expense_amount = parts[1].split('$')[1].strip() if '$' in parts[1] else '0'
            debtors = parts[2].split(' ')[-3:]
            expenses.append({
                "trip": note['title'],
                "expense_description": expense_description,
                "amount": expense_amount,
                "debtors": debtors
            })
print(expenses)

